}

.risk-gauge-block {
    display: flex;
    align-items: center;
    gap: 1.25rem;
}

.risk-circle-dial {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: #FEF2F2;
    border: 6px solid #EF4444;
