}
.risk-progression-timeline:before {
    content: '';
    position: absolute;
    top: 18px;
    left: 20px;
    right: 20px;
    height: 2px;
    background: #E2E8F0;
    z-index: 1;
}

.rp-stage {
    display: flex;
